// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.io.StringReader;
import java.util.ArrayList;
import java.util.List;

import org.eclipse.rdf4j.query.BindingSet;
import org.eclipse.rdf4j.query.QueryResults;
import org.eclipse.rdf4j.query.TupleQueryResult;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Verifies that the RDF4J extension functions (scalar functions, magic-property tuple functions, custom aggregates and
 * window functions) also work on the LMDB store, whose native evaluation path must fall back correctly for the new
 * algebra operators.
 */
public class LmdbExtensionFunctionSparqlTest {

	private static final String PREFIXES = "PREFIX strf: <http://rdf4j.org/function/string#>\n"
			+ "PREFIX arrf: <http://rdf4j.org/function/array#>\n" + "PREFIX agg: <http://rdf4j.org/aggregate#>\n"
			+ "PREFIX winf: <http://rdf4j.org/function/window#>\n" + "PREFIX mathf: <http://rdf4j.org/function/math#>\n"
			+ "PREFIX ex: <http://example.org/>\n";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	void setUp() throws Exception {
		repository = new SailRepository(
				new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)));
		String data = "@prefix ex: <http://example.org/> .\n"
				+ "ex:a ex:dept ex:sales ; ex:salary 10 ; ex:tags \"red,blue\" .\n"
				+ "ex:b ex:dept ex:sales ; ex:salary 30 ; ex:tags \"blue\" .\n"
				+ "ex:c ex:dept ex:eng ; ex:salary 50 ; ex:tags \"green\" .\n";
		try (RepositoryConnection conn = repository.getConnection()) {
			conn.add(new StringReader(data), "", RDFFormat.TURTLE);
		}
	}

	@AfterEach
	void tearDown() {
		repository.shutDown();
	}

	private List<BindingSet> query(String query) {
		try (RepositoryConnection conn = repository.getConnection();
				TupleQueryResult result = conn.prepareTupleQuery(PREFIXES + query).evaluate()) {
			return new ArrayList<>(QueryResults.asList(result));
		}
	}

	private static List<String> column(List<BindingSet> rows, String var) {
		List<String> values = new ArrayList<>();
		for (BindingSet row : rows) {
			values.add(row.hasBinding(var) ? row.getValue(var).stringValue() : null);
		}
		return values;
	}

	@Test
	void scalarFunction() {
		List<BindingSet> rows = query("SELECT ?s (mathf:sqrt(?salary) AS ?r) WHERE { ?s ex:salary ?salary }"
				+ " ORDER BY ?s");
		assertThat(column(rows, "r")).containsExactly("3.1622776601683795", "5.477225575051661",
				"7.0710678118654755");
	}

	@Test
	void magicProperty() {
		List<BindingSet> rows = query("SELECT ?s ?tag WHERE { ?s ex:tags ?tags . (?tags \",\") strf:split (?tag) }"
				+ " ORDER BY ?s ?tag");
		assertThat(column(rows, "tag")).containsExactly("blue", "red", "blue", "green");
		rows = query("SELECT ?n WHERE { (1 3) arrf:generateSeries (?n) }");
		assertThat(column(rows, "n")).containsExactly("1", "2", "3");
	}

	@Test
	void customAggregates() {
		List<BindingSet> rows = query("SELECT ?dept (agg:median(?salary) AS ?m) (agg:argMax(?s, ?salary) AS ?top)"
				+ " WHERE { ?s ex:dept ?dept ; ex:salary ?salary } GROUP BY ?dept ORDER BY ?dept");
		assertThat(column(rows, "m")).containsExactly("50", "20");
		assertThat(column(rows, "top")).containsExactly("http://example.org/c", "http://example.org/b");
	}

	@Test
	void windowFunctions() {
		List<BindingSet> rows = query("SELECT ?s (winf:rank(winf:orderBy(winf:desc(?salary))) AS ?rank)"
				+ " (winf:sum(?salary, winf:partitionBy(?dept)) AS ?deptTotal)"
				+ " WHERE { ?s ex:dept ?dept ; ex:salary ?salary } ORDER BY ?s");
		assertThat(column(rows, "rank")).containsExactly("3", "2", "1");
		assertThat(column(rows, "deptTotal")).containsExactly("40", "40", "50");
	}
}
